acc = np.array(accelerations)
t   = np.array(times)

# ── Find peak ─────────────────────────────────────────────────
peak_idx     = np.argmax(np.abs(acc))
peak_time    = t[peak_idx]
peak_acc     = acc[peak_idx]
peak_acc_g   = peak_acc / 9.81        # convert to g if in m/s²


class AccelerogramAnimation(Scene):
    def construct(self):
        template = TexTemplate()

        # ── Title
        #title = Text("Gorkha Earthquake Accelerogram", font_size=36, color=WHITE)
        
        title = MathTex(r"\mathbb{E}\text{arthquake}\ \mathbb{A}\text{ccelerogram}\ ", tex_template = template).to_edge(UP, buff = 1.2)
        title.set_color_by_gradient(YELLOW, GOLD_A, RED_A)
        title.scale(1.2)

        subtitle = MathTex("", font_size=27.).set_color_by_gradient(YELLOW, GOLD_A)

        subtitle = MathTex(r"\mathbb{N}\text{epal}\ \mathbb{E}\text{arthquake}\, 2015", tex_template = template).next_to(title, DOWN, buff = 0.15)

        subtitle.set_color_by_gradient(MAROON, PURPLE_A, RED)
        title_group = VGroup(title, subtitle).to_edge(UP, buff=0.3)

        initials = Text("@theoptimath", font="Yu Gothic UI", font_size=24)
        initials.set_opacity(0.3)
        initials.set_color_by_gradient(RED, ORANGE, YELLOW)
        initials.to_edge(DOWN, buff=1)

        self.add(title_group, initials)
        

        #Axes 
        x_max = float(t[-1]) * 1.05
        y_range_val = float(np.max(np.abs(acc))) * 1.4

        axes = Axes(
            x_range=[0, x_max, x_max / 5],
            y_range=[-y_range_val, y_range_val, y_range_val / 2],
            x_length=14.5,
            y_length=6,
            axis_config={
                "color": BLUE_C,
                "stroke_width": 3,
                "include_tip": True,
                "tip_length": 0.1,
                "tip_width": 0.2,
                'include_numbers':False,
                'include_ticks': False
            },
        ).shift(DOWN * 0.4)
        axes.y_axis.add_tip(at_start=True)

        x_label = axes.get_x_axis_label(
            MathTex("Time (s)", font_size=27, color=BLUE_C), direction=RIGHT).shift(DOWN * 0.6)
        y_label = axes.get_y_axis_label(
            MathTex("Ground-acceleration", font_size=27, color=BLUE_C),
            direction=LEFT, buff=3.2).shift(UP*0.3)

        self.add(axes, x_label, y_label)

        #zero_line = axes.get_horizontal_line(axes.c2p(x_max, 0), color=YELLOW_E, stroke_width=1)
        #self.play(Create(zero_line), run_time=0.5)

        points = [axes.c2p(float(t[i]), float(acc[i])) for i in range(len(t))]
        curve = VMobject()
        curve.set_points_as_corners(points)
        curve.set_stroke(color=ORANGE, width=1.5)

        shaking_text = Text("Shaking begins", font_size=20, color=RED).next_to(axes.c2p(0, 0), UR, buff=0.3)       
        shaking_ends_text = Text("Shaking ends", font_size=20, color=GREEN).next_to(axes.c2p(0, 0), UR, buff=0.3)

        shake_home = shaking_text.get_center().copy()

        def random_shake(mob, dt):
            mob.move_to(shake_home + np.array([
                random.uniform(-0.05, 0.05),
                random.uniform(-0.05, 0.05),
                0
            ]))

        shaking_text.add_updater(random_shake)

        self.play(FadeIn(shaking_text, shift= UP*0.2), run_time = 0.6)

        self.play(Create(curve), run_time=9, rate_func=linear)
        shaking_text.remove_updater(random_shake)
        self.play(ReplacementTransform(shaking_text, shaking_ends_text), run_time = 0.3)

        peak_dot = Dot(
            axes.c2p(float(peak_time), float(peak_acc)),
            radius=0.12, color=RED
        )
        peak_dot.set_z_index(5)

        # Vertical dashed line to x-axis
        v_line = DashedLine(
            axes.c2p(float(peak_time), 0),
            axes.c2p(float(peak_time), float(peak_acc)),
            color=RED, stroke_width=1.5, dash_length=0.1
        )

        # Horizontal dashed line to y-axis
        h_line = DashedLine(
            axes.c2p(0, float(peak_acc)),
            axes.c2p(float(peak_time), float(peak_acc)),
            color=RED, stroke_width=1.5, dash_length=0.1
        )

        self.play(
            Create(v_line), Create(h_line),
            GrowFromCenter(peak_dot),
            run_time=1.2
        )
        self.wait(0.3)

        sign = "+" if peak_acc > 0 else ""
        label_lines = [
            f"Peak Ground Acceleration",
            f"a = 0.17707g",
            f"t = {peak_time:.3f} s",
        ]

        ann_text = VGroup(*[
            Text(line, font_size=16, color=WHITE)
            for line in label_lines
        ]).arrange(DOWN, aligned_edge=LEFT, buff=0.1)

        ann_box = SurroundingRectangle(
            ann_text, color=RED, buff=0.18,
            fill_color="#1a0a0a", fill_opacity=0.85, stroke_width=1.5
        )
        annotation = VGroup(ann_box, ann_text)

        # Smart placement: above or below the peak dot
        dot_screen = axes.c2p(float(peak_time), float(peak_acc))
        if peak_acc > 0:
            annotation.next_to(peak_dot, UR, buff=0.25)
        else:
            annotation.next_to(peak_dot, DR, buff=0.25)

        # Keep annotation within frame
        annotation.shift(
            max(0, -6 + annotation.get_right()[0]) * LEFT +
            max(0, annotation.get_top()[1] - 3.7) * DOWN
        )

        annotation.shift(DOWN*1)

        self.play(FadeIn(annotation, shift=DOWN * 0.2), run_time=0.9)

        self.play(
            peak_dot.animate.scale(1.8).set_color(YELLOW),
            run_time=0.4
        )
        self.play(
            peak_dot.animate.scale(1 / 1.8).set_color(RED),
            run_time=0.4
        )
        self.play(
            peak_dot.animate.scale(1.5).set_color(YELLOW),
            run_time=0.3
        )
        self.play(
            peak_dot.animate.scale(1 / 1.5).set_color(RED),
            run_time=0.3
        )

        self.play(FadeOut(VGroup(
            title_group, axes, curve, #zero_line,
            x_label, y_label, v_line, h_line, shaking_text, shaking_ends_text,
            peak_dot, annotation
        )), run_time=1.2)
        self.wait(0.3)